    margin: 0;\r\n        padding: 0;\r\n      }\r\n\r\n      /* Header reset */\r\n      h1,\r\n      h2,\r\n      h3,\r\n      h4,\r\n      h5,\r\n      h6 {\r\n        display: block;\r\n        margin: 0;\r\n        padding: 0;\r\n      }\r\n\r\n      /* Image reset */\r\n      img,\r\n      a img {\r\n        border: 0;\r\n        height: auto;\r\n        outline: none;\r\n        text-decoration: none;\r\n      }\r\n\r\n      /* Better superscript */\r\n      sup {\r\n        font-size: 66%;\r\n        line-height: 1;\r\n        vertical-align: top;\r\n        mso-text-raise: 30%;\r\n      }\r\n\r\n      /* Force correct font size */\r\n      * {\r\n        -ms-text-size-adjust: 100%;\r\n        -webkit-text-size-adjust: 100%;\r\n        text-rendering: optimizeLegibility;\r\n        -webkit-font-smoothing: antialiased;\r\n      }\r\n\r\n      /* Prevent Outlook extra spacing */\r\n      table,\r\n      td {\r\n        mso-table-lspace: 0pt !important;\r\n        mso-table-rspace: 0pt !important;\r\n        mso-line-height-rule: exactly;\r\n        border-collapse: collapse !important;\r\n      }\r\n\r\n      /* Fix webkit padding */\r\n      table {\r\n        border-spacing: 0 !important;\r\n        border-collapse: collapse !important;\r\n        table-layout: fixed !important;\r\n      }\r\n\r\n      /* Default style for links. */\r\n      a {\r\n        text-decoration: underline;\r\n        color: #000000;\r\n        font-weight: bold;\r\n      }\r\n\r\n      /* Fix image rendering in IE */\r\n      img {\r\n        -ms-interpolation-mode: bicubic;\r\n      }\r\n\r\n      /* What it does:A work-around for email clients meddling in triggered links. */\r\n      a[x-apple-data-detectors],\r\n      /* iOS */\r\n      .unstyle-auto-detected-links a,\r\n      .aBn {\r\n        border-bottom: 0 !important;\r\n        cursor: default !important;\r\n        color: inherit !important;\r\n        text-decoration: none !important;\r\n        font-size: inherit !important;\r\n        font-family: inherit !important;\r\n        font-weight: inherit !important;\r\n        line-height: inherit !important;\r\n      }\r\n\r\n      /* What it does:Prevents Gmail from changing the text color in conversation threads. */\r\n      .im {\r\n        color: inherit !important;\r\n      }\r\n\r\n      /* What it does:Prevents Gmail from displaying a download button on large, non-linked images. */\r\n      u+img+div {\r\n        display: none !important;\r\n        opacity: 0.01 !important;\r\n      }\r\n\r\n      /* Center your email in Outlook.com */\r\n      .ExternalClass {\r\n        width: 100%;\r\n      }\r\n\r\n      .ExternalClass,\r\n      .ExternalClass p,\r\n      .ExternalClass span,\r\n      .ExternalClass font,\r\n      .ExternalClass td,\r\n      .ExternalClass div {\r\n        line-height: 100%;\r\n      }\r\n\r\n      img {\r\n        -ms-interpolation-mode: bicubic;\r\n      }\r\n\r\n      .yshortcuts a {\r\n        border-bottom: none !important;\r\n      }\r\n\r\n      .hide {\r\n        visibility: hidden;\r\n        display: none;\r\n        mso-hide: all;\r\n      }\r\n\r\n      .mbl-show {\r\n        display: none;\r\n        mso-hide: all;\r\n      }\r\n\r\n      #outlook a {\r\n        padding: 0;\r\n      }\r\n\r\n      /* Gmail link fix. Doesn't work for users who have images blocked by default */\r\n      u+#body a {\r\n        color: inherit;\r\n        font-size: inherit;\r\n        font-family: inherit;\r\n        font-weight: inherit;\r\n        line-height: inherit;\r\n      }\r\n\r\n      /* Gmail Android fix to add proper spacing */\r\n      div>u+.body .gm-spacing {\r\n        line-height: 100% !important;\r\n        height: 100% !important;\r\n      }\r\n\r\n      u+.compliance a,\r\n      p {\r\n        color: inherit;\r\n        font-size: inherit;\r\n        font-family: inherit;\r\n        font-weight: inherit;\r\n        line-height: inherit;\r\n      }\r\n\r\n      /* Gmail dark mode - prevents text color to be changed */\r\n      u+#body .gmail-blend-screen {\r\n        background: #000 !important;\r\n        mix-blend-mode: screen;\r\n      }\r\n\r\n      u+#body .gmail-blend-difference {\r\n        background: #000 !important;\r\n        mix-blend-mode: difference;\r\n      }\r\n\r\n      @media (prefers-color-scheme: dark) {\r\n\r\n        /* Shows Dark Mode-Only Content, Like Images */\r\n        .dark-img {\r\n          display: block !important;\r\n          width: auto !important;\r\n          overflow: visible !important;\r\n          float: none !important;\r\n          max-height: inherit !important;\r\n          max-width: inherit !important;\r\n          line-height: auto !important;\r\n          margin-top: 0px !important;\r\n          visibility: inherit !important;\r\n        }\r\n\r\n        /* Hides Light Mode-Only Content, Like Images */\r\n        .light-img {\r\n          display: none;\r\n          display: none !important;\r\n        }\r\n\r\n        /* Custom Dark Mode Background Color */\r\n        .darkmode {\r\n          background-color: #000000 !important;\r\n          background: #000000 !important;\r\n        }\r\n\r\n        .bgDarkmode {\r\n          background-color: #363836 !important;\r\n        }\r\n\r\n        .darkmode-white-border {\r\n          border-color: #ffffff !important;\r\n        }\r\n\r\n        /* Custom Dark Mode Font Colors */\r\n        h1,h2,h3,h4,h5,p,span,li,a,b {\r\n        color: #ffffff !important;\r\n        }\r\n\r\n        .ForceDark {\r\n          color: #000000 !important;\r\n        }\r\n      }\r\n    </style><style data-premailer="ignore">\r\n      /* MEDIA QUERIES */\r\n      @media screen and (max-width: 619px) {\r\n\r\n        .force-row,\r\n        .container {\r\n          width: 100% !important;\r\n          max-width: 100% !important;\r\n        }\r\n\r\n        /* What it does: Forces table cells into full-width rows. */\r\n        .mob-stack {\r\n          width: 100% !important;\r\